#pragma once
// strobf.h — compile-time string obfuscation for the needles/paths anti/*
// checks grep for (module names, emulator vendor strings, device paths).
//
// WHY NOT enc_strings.hpp: the rest of this project encrypts its strings
// with get_STR_*()/ChaCha20, generated by a CI step that isn't part of this
// source drop — enc_strings.hpp and chacha20.hpp are both CI-generated and
// neither ships here (see cheat.cpp's #include comment on enc_strings.hpp,
// and build.sh's "Requires: ... enc_strings.hpp already generated by CI").
// Wiring anti/* into that exact pipeline means guessing its key rotation /
// nonce scheme from the outside instead of reading it — not done here.
// This header does the same JOB for anti/* specifically — no plaintext
// needle/path bytes sitting in .rodata for `strings libcheat.so | grep -i
// frida` to read off for free — with a self-contained, CI-independent XOR
// obfuscation. Weaker than ChaCha20 (a few minutes of work to break by hand
// if someone targets this header specifically), but the actual threat this
// closes isn't cryptanalysis — it's a reverser running `strings` and
// getting a free list of exactly which checks exist and what they look
// for, before opening a disassembler at all. Plain XOR with a position-
// dependent key defeats that threat as completely as ChaCha20 would. Same
// tier as everything else in this directory: raises cost, doesn't survive
// someone who disassembles this header too.

#include <cstddef>
#include <cstdint>

namespace strobf {

// Not a secret — just enough that the obfuscated bytes aren't a single
// repeating-byte XOR of the plaintext (which both `strings`' own heuristics
// and a two-second brute-force script would still see through).
constexpr uint8_t kBase = 0xB7;

template <size_t N>
struct Obfuscated {
    char data[N];
    constexpr Obfuscated(const char (&s)[N]) : data{} {
        for (size_t i = 0; i < N; ++i)
            data[i] = (char)(s[i] ^ (uint8_t)(kBase + i * 41));
    }
};

template <size_t N>
inline void decode(const Obfuscated<N>& o, char (&out)[N]) {
    for (size_t i = 0; i < N; ++i)
        out[i] = (char)(o.data[i] ^ (uint8_t)(kBase + i * 41));
}

} // namespace strobf

// Expands to a const char* holding `s` decoded into thread-local storage.
// Deliberately NOT cached behind a function-local `static` guard: antidbg's
// own checks run from more than one thread in PAYLOAD (init_thread's
// one-shot gate and hk_update's per-frame recheck are different threads —
// see cheat.cpp), and a `static`-once-initialized decode would hand every
// thread but the first a pointer into a thread_local buffer that thread
// never wrote to. So OBF() re-decodes on every call instead — a handful of
// XOR'd bytes, not worth trading correctness for. The returned pointer
// stays valid for the calling thread's lifetime (thread_local storage), so
// it's safe to use anywhere in the expression that invoked OBF(), just
// don't stash it past the next OBF() call on the same thread with the
// same N (each call site has its own buffer, only same-site reentrancy —
// not expected here — would collide).
#define OBF(s)                                                               \
    ([]() -> const char* {                                                   \
        constexpr auto _obf = strobf::Obfuscated(s);                         \
        thread_local char _buf[sizeof(s)];                                   \
        strobf::decode(_obf, _buf);                                          \
        return _buf;                                                         \
    }())
